        coalesce(rollup.count_distinct_device_id_is_login_failed_is_ios_l30d, 0) as count_distinct_device_id_is_login_failed_is_ios_l30d,
        {{ fs_array_size(fs_array_union2("at_state.p_count_distinct_device_id_is_login_failed_is_ios", "at_recent.p_count_distinct_device_id_is_login_failed_is_ios")) }} as count_distinct_device_id_is_login_failed_is_ios_all_time,
        coalesce(rollup.count_distinct_device_id_is_login_failed_is_android_l7d, 0) as count_distinct_device_id_is_login_failed_is_android_l7d,
