    cast(count_event_id_is_office_hours_all_time as bigint) as count_event_id_is_office_hours_all_time,
    cast(count_event_id_is_evening_leisure_l7d as bigint) as count_event_id_is_evening_leisure_l7d,
    cast(count_event_id_is_evening_leisure_l14d as bigint) as count_event_id_is_evening_leisure_l14d,
    cast(count_event_id_is_evening_leisure_l30d as bigint) as count_event_id_is_evening_leisure_l30d,
