    cast({{ fs_datediff_day("min_event_timestamp_is_login_failed_is_others_all_time", fs_target_date()) }} as bigint) as max_days_since_login_is_login_failed_is_others_all_time,

    cast(_first_event_date as date) as _first_event_date,
    cast(_last_event_date as date) as _last_event_date,
    cast({{ dbt.current_timestamp() }} as timestamp) as _generated_at,
    cast('a7a086250bfc' as string) as _spec_version
from joined
